package net.civeira.phylax.features.access.userinvitation.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.userinvitation.domain.UserInvitation;
import net.civeira.phylax.features.access.userinvitation.domain.valueobject.EmailVO;

@RequiredArgsConstructor
public class EmailValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<EmailVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param email
   * @return
   */
  public T email(EmailVO email) {
    this.value = Optional.of(email);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param email
   * @return
   */
  public T email(Optional<EmailVO> email) {
    this.value = email;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param email
   * @return
   */
  public T email(String email) {
    this.value = Optional.of(EmailVO.from(email));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getEmail() {
    return value.map(EmailVO::getEmail);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<EmailVO> getEmailValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public EmailVO readEmail(final Optional<UserInvitation> original,
      final ConstraintFailList fails) {
    EmailVO result = value.orElse(original.map(UserInvitation::getEmailValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "email", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetEmail() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetEmailIfMatches(final String field) {
    if ("email".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
